def remove_numbers_in_remove_string_from_big_string():
    big_list = big_string.split('|')
    remove_list = remove_string.split('|')
    print('big_list: ',len(big_list))
    for number in remove_list:
        if number in big_list:
            big_list.remove(number)
    print('big_list_removed: ',len(big_list))
    return '|'.join(big_list)

